CREATE TABLE IF NOT EXISTS ai_ops_chat (id bigint PRIMARY KEY AUTO_INCREMENT,owner_id bigint NOT NULL,title varchar(100) NOT NULL,created_at bigint NOT NULL,updated_at bigint NOT NULL,KEY idx_ai_chat_owner(owner_id,updated_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ai_ops_chat_turn (id bigint PRIMARY KEY AUTO_INCREMENT,chat_id bigint NOT NULL,user_content text NOT NULL,policy_json text NOT NULL,status varchar(24) NOT NULL,events mediumtext,created_at bigint NOT NULL,finished_at bigint,KEY idx_ai_turn(chat_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
